def f(x, y, z, a, b, c):
    """Calculates the value of the function f."""
    term1 = abs(x + y - a - b)
    term2 = abs(y + z - b - c)
    term3 = abs(z + x - c - a)
    return term1 + term2 + term3

max_M_prime = 0

# Iterate over all possible true integer choices (x, y, z)
for x in range(10):
    for y in range(10):
        for z in range(10):

