import itertools

def f(x, y, z, a, b, c):
    """Calculates the function value f(x, y, z; a, b, c)."""
    term1 = abs((x + y) - (a + b))
    term2 = abs((y + z) - (b + c))
    term3 = abs((z + x) - (c + a))
    return term1 + term2 + term3

max_distinct_values = 0

# Iterate over all possible queries (a, b, c) except (0, 0, 0)
for a in range(10):
    for b in range(10):
        for c in range(10):
            if a == 0 and b == 0 and c == 0:
                continue

            # For this fixed query (a, b, c), find all distinct values generated by varying (x, y, z)
            distinct_values = set()

            # Iterate over all possible choices (x, y, z)
            for x, y, z in itertools.product(range(10), repeat=3):
                value = f(x, y, z, a, b, c)
                distinct_values.add(value)

            # Update the maximum number of distinct values found so far
            current_count = len(distinct_values)
            if current_count > max_distinct_values:
                max_distinct_values = current_count

print(f"The maximum number of distinct values M' is: {max_distinct_values}")
if max_distinct_values > 28:
    print("M' > 28 is True")
else:
    print("M' > 28 is False")

